// Cargar cajas de 30 kg en un camión de 100 kg de capacidad, mostrando cada vuelta
const capacidad = 100;
const pesoCaja = 30;
let peso = 0;       // 1. preparar
let cajas = 0;

while (peso + pesoCaja <= capacidad) {          // 2. condición: ¿entra otra caja?
  console.log("vuelta " + (cajas + 1) + ": peso " + peso + " + " + pesoCaja + " = " + (peso + pesoCaja) + " (entra)");
  peso = peso + pesoCaja;                       // 3. avanzar: algo cambia
  cajas = cajas + 1;
}
console.log("sale del bucle con peso " + peso + " y " + cajas + " cajas");
console.log("la próxima caja daría " + (peso + pesoCaja) + ": no entra");

// Con los datos de verdad: camión de 1.000 kg y cajas de 35 kg
let p2 = 0, c2 = 0;
while (p2 + 35 <= 1000) { p2 += 35; c2 += 1; }
console.log("1000 kg / cajas de 35 kg ->", c2, "cajas,", p2, "kg");

// Las tres partes de un for, y su equivalente con while
for (let i = 0; i < 4; i++) {
  console.log("for:   i vale " + i);
}

let j = 0;
while (j < 4) {
  console.log("while: j vale " + j);
  j++;
}

// Una lista se escribe entre corchetes. Acá solo la recorremos; las listas se estudian más adelante.
const bultos = [3, 5, 2, 4];   // bultos de cuatro paradas

let total = 0;
for (let i = 0; i < bultos.length; i++) {
  total += bultos[i];
  console.log("i = " + i + "  bultos[i] = " + bultos[i] + "  total = " + total);
}
console.log("total de bultos:", total);

// El mismo recorrido, pero con el límite mal puesto (<= en lugar de <)
let malTotal = 0;
for (let i = 0; i <= bultos.length; i++) {
  malTotal += bultos[i];
  console.log("i = " + i + "  bultos[i] = " + bultos[i] + "  malTotal = " + malTotal);
}

const estados = ["entregado", "ausente", "entregado", "cancelado", "entregado", "ausente", "entregado"];

// for…of: recorre los valores, sin índice y sin límite que equivocar
let entregados = 0;
for (const estado of estados) {
  if (estado === "entregado") {
    entregados++;
  }
}
console.log("entregados:", entregados, "de", estados.length);

// continue: saltea la parada cancelada y sigue con la próxima
let aVisitar = 0;
for (const estado of estados) {
  if (estado === "cancelado") {
    continue;
  }
  aVisitar++;
}
console.log("paradas a visitar (sin canceladas):", aVisitar);

// break: corta todo el bucle apenas aparece la primera ausencia
let hastaLaPrimeraAusencia = 0;
for (const estado of estados) {
  if (estado === "ausente") {
    break;
  }
  hastaLaPrimeraAusencia++;
}
console.log("entregas seguidas antes de la primera ausencia:", hastaLaPrimeraAusencia);

// Una condición que nunca se vuelve falsa, con una válvula de seguridad para poder mostrarla
let i = 0;
let vueltas = 0;
while (i < 5) {
  // se olvidó el i++ : i nunca cambia
  vueltas++;
  if (vueltas > 1000000) {   // la válvula: sin esto el bucle no terminaría nunca
    console.log("corté a la fuerza en la vuelta " + vueltas + ", con i = " + i);
    break;
  }
}

// Un caso más traicionero: avanzar de a 0,1 y esperar llegar justo a 1
let x = 0;
let pasos = 0;
while (x !== 1 && pasos < 14) {
  x += 0.1;
  pasos++;
  console.log("paso " + pasos + ": x = " + x);
}
console.log("¿x es exactamente 1?", x === 1);

// do…while: el cuerpo corre una vez ANTES de preguntar
const atendio = [false, false, true, true];   // qué pasó en cada intento de entrega
let intento = 0;
let entregado;

do {
  entregado = atendio[intento];
  intento++;
  console.log("intento " + intento + ": " + (entregado ? "atendieron" : "nadie atiende"));
} while (!entregado && intento < 3);

console.log("intentos usados:", intento, "| entregado:", entregado);

// while contra do…while cuando la condición es falsa desde el principio
let a = 10;
let vecesWhile = 0;
while (a < 5) { vecesWhile++; }
let b = 10;
let vecesDo = 0;
do { vecesDo++; } while (b < 5);
console.log("while corrió " + vecesWhile + " veces; do…while corrió " + vecesDo + " vez.");

// Versión reducida, escrita para este día, de cómo Senda calcula el nivel de una persona según sus pasos.
function pasosHasta(nivel) {
  const n = Math.max(1, Math.floor(nivel)) - 1;
  return 100 * n + 25 * n * (n - 1);
}

function nivelDe(pasos) {
  let nivel = 1;
  let vueltas = 0;
  while (pasosHasta(nivel + 1) <= pasos && nivel < 999) {
    nivel += 1;
    vueltas++;
  }
  return { nivel, vueltas };
}

for (const p of [0, 99, 100, 249, 250, 449, 450, 5000]) {
  const r = nivelDe(p);
  console.log(p + " pasos -> nivel " + r.nivel + " (el bucle dio " + r.vueltas + " vueltas)");
}

// Acumuladores: varias cosas se juntan en un solo recorrido
const bultos = [3, 5, 2, 4, 0, 6, 1];

let total = 0;            // suma
let conBultos = 0;        // contador
let maximo = bultos[0];   // máximo: se arranca con un valor real de la lista, no con 0
let texto = "";           // texto que se va armando

for (const b of bultos) {
  total += b;
  if (b > 0) conBultos++;
  if (b > maximo) maximo = b;
  texto += b + " ";
}
console.log("suma:", total, "| paradas con bultos:", conBultos, "| máximo:", maximo);
console.log("promedio por parada:", (total / bultos.length).toFixed(2));
console.log("texto armado: " + texto);

// Doble bucle: por cada zona, probamos cada tramo de peso (la tabla de tarifas del día anterior)
const zonas = ["caba", "gba", "interior"];
const bases = [4000, 6500, 11000];
const factores = [1, 1.5, 2.2];      // hasta 5 kg, hasta 20 kg, hasta 50 kg

let cuentas = 0;
for (let z = 0; z < zonas.length; z++) {
  let fila = zonas[z] + ":";
  for (let t = 0; t < factores.length; t++) {
    fila += " " + Math.round(bases[z] * factores[t]);
    cuentas++;
  }
  console.log(fila);
}
console.log("cuentas hechas:", cuentas, "(3 zonas × 3 tramos)");

// Cuántas comparaciones hace un doble bucle que mira cada par de entregas (buscando duplicados)
function comparaciones(n) {
  let veces = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      veces++;
    }
  }
  return veces;
}
console.log("10 entregas    ->", comparaciones(10));
console.log("100 entregas   ->", comparaciones(100));
console.log("1000 entregas  ->", comparaciones(1000));
console.log("2000 entregas  ->", comparaciones(2000));
console.log("6 pedidos      ->", comparaciones(6));
